        # Set up steps ...

      - name: Render site
        id: render
        run: |
          set +e
          set -o pipefail
          quarto render 2&gt;&1 | tee render-output.txt
          status=${PIPESTATUS[0]}
          set -e

          sed 's/\x1b\[[0-9;]*[a-zA-Z]//g' render-output.txt \
            | grep -E 'WARNING:|\[WARNING\]|ERROR:|\[ERROR\]|Unable to resolve' \
            &gt; render-warnings.txt || true

          if [ ! -s render-warnings.txt ] && [ "$status" != "0" ]; then
            tail -n 80 render-output.txt &gt; render-warnings.txt
          fi

          failed=false
          if [ "$status" != "0" ] || [ -s render-warnings.txt ]; then
            failed=true
          fi

          echo "exit_code=$status" &gt;&gt; "$GITHUB_OUTPUT"
          echo "failed=$failed" &gt;&gt; "$GITHUB_OUTPUT"
          cat render-warnings.txt

      - name: Comment on PR
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const marker = '&lt;!-- quarto-render-pr-comment --&gt;';
            const failed = '${{ steps.render.outputs.failed }}' === 'true';
            const renderFailed = '${{ steps.render.outputs.exit_code }}' !== '0';
            let output = '';
            if (fs.existsSync('render-warnings.txt')) {
              output = fs.readFileSync('render-warnings.txt', 'utf8').trim();
            }
            const max = 60000;
            if (output.length &gt; max) {
              output = output.slice(0, max) + '\n\n…truncated';
            }

            const heading = renderFailed
              ? 'Quarto render failed'
              : failed
                ? 'Render warnings found'
                : 'No render warnings found';
            const body = failed
              ? `${marker}\n## ${heading}\n\n\`\`\`text\n${output}\n\`\`\``
              : `${marker}\n## ${heading}`;

            const comments = await github.paginate(github.rest.issues.listComments, {
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
            });
            const existing = comments.find((c) =&gt; c.body?.includes(marker));

            if (existing) {
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: existing.id,
                body,
              });
            } else {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body,
              });
            }


Quarto can finish a render with a successful exit code even when links do not resolve, so the workflow treats WARNING and ERROR lines as failures.

